class Solution:
    def shortestSequence(self, rolls, k):
        seen = set()
        blocks = 0
        for r in rolls:
            seen.add(r)
            if len(seen) == k:
                blocks += 1
                seen.clear()
        return blocks + 1

c.cpp:
class Solution {
public:
    int shortestSequence(vector<int>& rolls, int k) {
        vector<bool> seen(k + 1, false);
        int cnt = 0, blocks = 0;
        for (int r : rolls) {
            if (!seen[r]) { seen[r] = true; cnt++; }
            if (cnt == k) {
                blocks++;
                cnt = 0;
                fill(seen.begin(), seen.end(), false);
            }
        }
        return blocks + 1;
    }
};

