class Solution {
    public int shortestSequence(int[] rolls, int k) {
        boolean[] seen = new boolean[k + 1];
        int cnt = 0, blocks = 0;
        for (int r : rolls) {
            if (!seen[r]) { seen[r] = true; cnt++; }
            if (cnt == k) {
                blocks++;
                cnt = 0;
                Arrays.fill(seen, false);
            }
        }
        return blocks + 1;
    }
}

